public void testSwitchMapClosure_8_oe() {
    final MockClosure<String> a = new MockClosure<>();
    final MockClosure<String> b = new MockClosure<>();
    final Map<String, Closure<String>> map = new HashMap<>();
    map.put("HELLO", a);
    map.put("THERE", b);
    ClosureUtils.switchMapClosure(map).execute(null);

    a.reset();
    b.reset();
    map.clear();
    map.put("HELLO", a);
    map.put("THERE", b);
    ClosureUtils.switchMapClosure(map).execute("THERE");

    a.reset();
    b.reset();
    map.clear();
    final MockClosure<String> c = new MockClosure<>();
    map.put("HELLO", a);
    map.put("THERE", b);
    map.put(null, c);
    ClosureUtils.switchMapClosure(map).execute("WELL");

    assertEquals(NOPClosure.INSTANCE, ClosureUtils.switchMapClosure(new HashMap<String, Closure<String>>()));
}

focal_method:
@SuppressWarnings("unchecked")
    public static <E> Closure<E> switchMapClosure(final Map<? extends E, Closure<E>> objectsAndClosures) {
        if (objectsAndClosures == null) {
            throw new NullPointerException("The object and closure map must not be null");
        }
        final Closure<? super E> def = objectsAndClosures.remove(null);
        final int size = objectsAndClosures.size();
        final Closure<? super E>[] trs = new Closure[size];
        final Predicate<E>[] preds = new Predicate[size];
        int i = 0;
        for (final Map.Entry<? extends E, Closure<E>> entry : objectsAndClosures.entrySet()) {
            preds[i] = EqualPredicate.<E>equalPredicate(entry.getKey());
            trs[i] = entry.getValue();
            i++;
        }
        return ClosureUtils.<E>switchClosure(preds, trs, def);
    }

