        boolean match = false;
        for (int j = 0; j < array.length; j++) {
            if (matched[j]) {
                continue;
            }
            if (array[i] == confirmedArray[j]
                    || array[i] != null && array[i].equals(confirmedArray[j])) {
                matched[j] = true;
                match = true;
                break;
            }
        }
        if (!match) {
            fail("element " + i + " in returned array should be found " + "in the confirmed collection's array");
}
}
}

