    Collections.sort(newSortedKeys, new ReverseComparator<>(ComparableComparator.<K>comparableComparator()));
    newSortedKeys = Collections.unmodifiableList(newSortedKeys);

    final Iterator<K> mapIter = sm.keySet().iterator();
