    final SetUniqueList<E> lset = new SetUniqueList<>(new ArrayList<E>(), new HashSet<E>());

    final E obj1 = (E) Integer.valueOf(1);
    final E obj2 = (E) Integer.valueOf(2);
    final E obj3 = (E) Integer.valueOf(3);

    lset.add(obj1);
    lset.add(obj2);
    lset.set(0, obj1);

    lset.clear();
    lset.add(obj1);
    lset.add(obj2);
    lset.set(0, obj2);

    lset.clear();
    lset.add(obj1);
    lset.add(obj2);
    lset.set(0, obj3);
    assertSame(obj3, lset.get(0));
}

