public void testTransformedSet_decorateTransform_1_oe() {
    final Set<Object> originalSet = new HashSet<>();
    final Object[] els = new Object[] {"1", "3", "5", "7", "2", "4", "6"};
    Collections.addAll(originalSet, els);
