public void testGetByIndex_1_oe() {
    resetEmpty();
    ListOrderedMap<K, V> lom = getMap();
    try {
        lom.get(0);
    } catch (final IndexOutOfBoundsException ex) {}
    try {
        lom.get(-1);
    } catch (final IndexOutOfBoundsException ex) {}

    resetFull();
    lom = getMap();
    try {
        lom.get(-1);
    } catch (final IndexOutOfBoundsException ex) {}
    try {
        lom.get(lom.size());
    } catch (final IndexOutOfBoundsException ex) {}

    int i = 0;
    for (final MapIterator<K, V> it = lom.mapIterator(); it.hasNext(); i++) {
        assertSame(it.next(), lom.get(i));
}
}

focal_method:
@Override
    public E next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        final E x = slotFilled ? slot : iterator.next();
        // reset the lookahead slot
        slot = null;
        slotFilled = false;
        return x;
    }

